    HarnessGuid GetGUID() const { return harnessGuid; }

    // Harness-only: the verified tail of Player::RewardQuest, using the two
    // verbatim pinned callees (check_core_reward_and_remove_bookkeeping).
    void HarnessRewardLikeCore(uint32 questId)
    {
        RemoveActiveQuest(questId, false);
        SetRewardedQuest(questId);
    }

