    QuestStatusSaveMap m_QuestStatusSave;
    RewardedQuestSet m_RewardedQuests;
    QuestStatusSaveMap m_RewardedQuestsSave;

    bool harnessInWorld = true;
    bool harnessSeasonalAvailable = true;
    HarnessGuid harnessGuid{0x1234};
